    biography: "Brian Yen is a Principal at Headline, based in Taipei within the firm's Asia team. He focuses on enterprise solutions, fintech and semiconductors, targeting sectors where massive value can be created by bringing in digitisation. His listed portfolio companies are BlueX, Kiwibot, Zaiko, TMYTEK, ICW, 17Live and Capitalise.ai. He describes having had analytical training from the other side of the table before concluding that early-stage involvement is the most impactful. He names belief in long-termism as the most important trait in an investor.",
