    biography: "Inigo Garcia Gordobil is a Partner and Global Head of Investor Relations at Headline, based in San Francisco. He has over fifteen years of venture capital experience across strategic and investor relations roles and institutional investing. He was previously Partner and Head of Investor Relations at Base10, where he helped scale the firm to more than $2.5B of assets under management. Before that he was an institutional investor at Cambridge Associates, where he co-led US venture capital and growth equity research and directed Latin America private investments. He is a native Spanish speaker and also speaks Basque, Italian, French and Portuguese.",
