    biography: "Zvika Orron is a Managing Partner at Viola Ventures, which he joined in 2017 when the fund rebranded from Carmel Ventures. He was previously co-founder and CTO of Vi (LifeBEAM), an AI-based fitness technology company, and before that served 18 years as an operational pilot in the Israeli Air Force. He leads Viola Ventures' deep tech practice, covering semiconductors, AI infrastructure, AI-based vertical applications and cybersecurity. His portfolio includes Speedata, Immunai, proteanTecs, Taranis, Impala AI, PhaseV and QuamCore. He holds B.Sc. and M.Sc. degrees in Biomedical Engineering from Tel Aviv University, both Magna Cum Laude.",
