    biography: "Ganesh Rengaswamy is a co-founder and Managing Partner at Quona Capital, based in Bangalore, where he covers Asia. Before Quona he led Asia operations for Accion's Frontier Investments Group, was a General Partner at Lok Capital, served as Asia Director for Unitus Inc., and helped facilitate Greylock Partners' entry into the Indian market. Earlier he co-founded a company that was acquired by Travelocity and held customer acquisition and growth roles at Infosys. Quona's profile lists his investments and advisory work with SKS/Bharat Financial Inclusion, Ujjivan, Equitas, IFMR/Northern Arc, Vistaar, TechProcess and Bandhan, and cites portfolio exits including IndiaMART's IPO, Gojek and Shubham's acquisition by Premji Invest. He has advised Village Capital, Accion Venture Lab, the GSF Accelerator and IIM-Ahmedabad. Quona's site does not publish his education.",
