    biography: "Monica Brand Engel is a co-founding Managing Partner of Quona Capital, where she invests in fintech companies serving underserved customers in emerging markets. Before Quona she was founding Managing Director of Accion's Frontier Investments Group, the predecessor vehicle from which Quona emerged, and earlier worked in Accion's Product Innovation Group and with Gentera (Compartamos) Bank in Mexico. She also founded Anthuri Catalysts in South Africa and worked at Calvert Ventures. Quona lists her current board seats as Sokowatch, Yoco, Azimo, GloboKasNet, Tiaxa and Zoona, and prior board roles including Gentera Bank, Shubham Housing, AllLife, Paralife and Pay Rent Builds Credit. She is a founding member of the EMPEA Impact Council and chairs the Investor Representative Committee at LeapFrog Investments. She holds an MBA and an MA in Education from Stanford and a BA in Economics from Williams College.",
