    biography: "Ameya Upadhyay is a General Partner at Flourish Ventures, based in London, investing in founders building critical financial infrastructure across Africa, the Middle East and other emerging markets, with a focus on global payments infrastructure including cross-border and blockchain-native companies. He led Flourish's pre-seed investment in Flutterwave and played a principal role in launching Madica, an Africa-focused pre-seed investment program. Before Flourish he worked at Omidyar Network and was a consultant at Bain & Company. Flourish lists his portfolio including Flutterwave, FairMoney, Apollo Agriculture, Flash, HoneyCoin, Lidya, littlefish, Lua, MaxAB, MoneyHash, Pula, Stitch and Zone. He holds an engineering degree from Delhi College of Engineering and an MBA from IIM Ahmedabad. Flourish's site does not state the year he joined.",
